  brush.vertex(200, 300); // Bottom of hills
  brush.vertex(300, 250); // Left side of hills
  brush.endShape(true);

  brush.fill("#3498db", 70); // Hill color
  brush.beginShape(0.8); // Curvature
  brush.vertex(150, 250); // Top of hills
  brush.vertex(150, 200); // Right side of hills
  brush.vertex(150, 150); // Bottom of hills
  brush.vertex(100, 200); // Left side of hills
  brush.endShape(true);

  brush.noStroke();
